  ($str$desmear_and_plate_through_holes$str$, $str$Plating Line - 6 Gating Tanks - 1600mm x 650mm$str$, 2.3, 85.18, 5.16, $str$Desmear and Plate Through Holes:Plating Line - 6 Gating Tanks - 1600mm x 650mm:India$str$),
  ($str$desmear_and_plate_through_holes$str$, $str$Plating Line - 8 Gating Tanks - 2000mm x 650mm$str$, 2.3, 127.78, 6.57, $str$Desmear and Plate Through Holes:Plating Line - 8 Gating Tanks - 2000mm x 650mm:India$str$),
  ($str$develop_solder_mask$str$, $str$Solder Mask Developer (8m x 1.7m)$str$, 1.73, 22.62, 1.26, $str$Develop Solder Mask:Solder Mask Developer (8m x 1.7m):India$str$),
  ($str$dissolve_unexposed_photo_resist$str$, $str$Photo Resist Developer (8m x 1.7m)$str$, 2.3, 15.28, 1.26, $str$Dissolve Unexposed Photo Resist:Photo Resist Developer (8m x 1.7m):India$str$),
  ($str$drill_circuit_holes$str$, $str$Excellon HS 1L 2 heads 1 station$str$, 1.73, 4.63, 1.03, $str$Drill Circuit Holes:Excellon HS 1L 2 heads 1 station:India$str$),
