  ($str$drill_registration_holes$str$, $str$Via Mechanics ND-1A281$str$, 1.73, 4.39, 0.97, $str$Drill Registration Holes:Via Mechanics ND-1A281:India$str$),
  ($str$electroless_nickel_immersion_gold$str$, $str$High Capacity Plating Line$str$, 2.3, 170.37, 17.93, $str$Electroless Nickel Immersion Gold:High Capacity Plating Line:India$str$),
