  ($str$pcb_stamp$str$, $str$Ascen ASPM-10T$str$, 1.73, 1.03, 0.89, $str$Stamp:Ascen ASPM-10T:India$str$),
  ($str$pcb_stamp$str$, $str$Stamping Press Large$str$, 1.73, 1.51, 0.89, $str$Stamp:Stamping Press Large:India$str$),
  ($str$pcb_stamp$str$, $str$Yush Electronics YSPE 8 Ton$str$, 1.73, 1.5, 0.89, $str$Stamp:Yush Electronics YSPE 8 Ton:India$str$),
