  ($str$tack_dry_solder_mask$str$, $str$Rack 1m x 1m x 1m - BedSize$str$, 1.73, 3.51, 0.93, $str$Tack Dry Solder Mask:Rack 1m x 1m x 1m - BedSize:India$str$),
  ($str$wet_film_solder_mask$str$, $str$ATMA PC 68$str$, 2.3, 3.03, 0.99, $str$Wet Film Solder Mask:ATMA PC 68:India$str$),
  ($str$wet_film_solder_mask$str$, $str$ATMA PC 71$str$, 2.3, 3.57, 1.02, $str$Wet Film Solder Mask:ATMA PC 71:India$str$),
  ($str$wet_film_solder_mask$str$, $str$Circuit Automation DP3500$str$, 2.3, 9.95, 1.09, $str$Wet Film Solder Mask:Circuit Automation DP3500:India$str$),
  ($str$wet_film_solder_mask$str$, $str$Sirimac 4152CCD$str$, 2.3, 4.25, 0.92, $str$Wet Film Solder Mask:Sirimac 4152CCD:India$str$),
  ($str$wet_film_solder_mask$str$, $str$Thieme 1000 E$str$, 2.3, 4.78, 0.99, $str$Wet Film Solder Mask:Thieme 1000 E:India$str$)
  ) AS v(machine_class, machine_name, labor, direct, indirect, source_key)
  LOOP
    -- The oldest USA row: a database where migration 797 ran twice holds two identical rows per machine.
    SELECT id INTO usa_id FROM mhr_records
    WHERE location = 'USA' AND process_group = 'PCB' AND machine_class = r.machine_class AND machine_name = r.machine_name
    ORDER BY created_at, id
    LIMIT 1;
    IF usa_id IS NULL THEN
      missing := array_append(missing, r.machine_class || ':' || r.machine_name);
      CONTINUE;
    END IF;
    IF EXISTS (SELECT 1 FROM mhr_records m WHERE m.location = 'India' AND m.machine_class = r.machine_class AND m.machine_name = r.machine_name) THEN
      CONTINUE;
    END IF;
    EXECUTE format('INSERT INTO mhr_records (%s) SELECT %s FROM mhr_records usa_row WHERE usa_row.id = $1', cols, sel)
      USING usa_id, r.direct, r.indirect, r.labor, 'India', 'IN', r.source_key;
    n := n + 1;
  END LOOP;

  RAISE NOTICE 'PCB India rows inserted: %', n;
  IF array_length(missing, 1) > 0 THEN
    RAISE EXCEPTION 'PCB machines with no USA row (migration 797): %', missing;
  END IF;
END $pcb_machines$;

